css:
footer{background:#fff;border:0}
footer hr{display:none}
nav{display:grid;grid-template-columns:repeat(8,1fr);gap:0 24px;border:0}
nav h3::before{content:"▶";color:#9b2c3a;font-size:.65em;margin-right:.5em}
nav li::before{content:"・";color:#b9a9a5}
.legal{margin-top:56px;font-size:10px;color:#9a9a9a;border:0}
.dotline{height:1px;background-image:radial-gradient(#d9b3b5 1px,transparent 1px);background-size:6px 1px}
